    function initHlsVideo(videoElement, hlsSrc, options = {}) {
      if (!videoElement || !hlsSrc) return null;
      const { autoplay = true, startHighQuality = true } = options;
      const shouldLoop = videoElement.hasAttribute("loop");
      if (shouldLoop) {
        videoElement.removeAttribute("loop");
      }
      if (Hls.isSupported()) {
        const hlsConfig = {
          enableWorker: true,
          lowLatencyMode: false,
          backBufferLength: 90,
          maxBufferLength: 600,
          // Keep up to 10 minutes of video in buffer
          maxMaxBufferLength: 600
        };
        if (startHighQuality) {
          hlsConfig.startLevel = -1;
          hlsConfig.capLevelToPlayerSize = false;
          hlsConfig.abrEwmaDefaultEstimate = 5e6;
        }
        const hls = new Hls(hlsConfig);
        hls.loadSource(hlsSrc);
        hls.attachMedia(videoElement);
        hls.on(Hls.Events.MANIFEST_PARSED, (event2, data) => {
          if (startHighQuality) {
            const highestLevel = data.levels.length - 1;
            hls.startLevel = highestLevel;
            hls.currentLevel = highestLevel;
          }
          if (autoplay) {
            videoElement.play().catch((e) => {
              console.warn("Video autoplay prevented:", e);
            });
          }
        });
        if (shouldLoop) {
          videoElement.addEventListener("ended", () => {
            videoElement.currentTime = 0;
            videoElement.play().catch((e) => {
              console.warn("Video loop replay prevented:", e);
            });
          });
        }
        hls.on(Hls.Events.ERROR, (event2, data) => {
          if (data.fatal) {
            console.error("Fatal HLS error:", data);
            switch (data.type) {
              case Hls.ErrorTypes.NETWORK_ERROR:
                hls.startLoad();
                break;
              case Hls.ErrorTypes.MEDIA_ERROR:
                hls.recoverMediaError();
                break;
              default:
                hls.destroy();
                break;
            }
          }
        });
        return hls;
      }
      if (videoElement.canPlayType("application/vnd.apple.mpegurl")) {
        videoElement.src = hlsSrc;
        if (shouldLoop) {
          videoElement.addEventListener("ended", () => {
            videoElement.currentTime = 0;
            videoElement.play().catch((e) => {
              console.warn("Video loop replay prevented:", e);
            });
          });
        }
        if (autoplay) {
          videoElement.addEventListener("loadedmetadata", () => {
            videoElement.play().catch((e) => {
              console.warn("Video autoplay prevented:", e);
            });
          });
        }
        return null;
      }
      return null;
    }
